INSERT INTO public.organization_symbols (
  organization_id, symbol_name, symbol_url, jurisdiction_scope, valid_from, valid_to,
  is_current, statutory_order_ref, data_status, provenance_id, created_at, updated_at
)
SELECT i.* FROM incoming_symbols i
WHERE NOT EXISTS (
  SELECT 1 FROM public.organization_symbols e
  WHERE e.organization_id = i.organization_id
    AND e.symbol_name = i.symbol_name
    AND e.valid_from = i.valid_from
);

