INSERT INTO public.organization_aliases (
  raw_lookup_key, raw_original_string, organization_id, alias_type, jurisdiction_scope,
  valid_from, valid_to, confidence, provenance_id, created_at, updated_at
)
SELECT i.* FROM incoming_aliases i
WHERE NOT EXISTS (
  SELECT 1 FROM public.organization_aliases e
  WHERE e.raw_lookup_key = i.raw_lookup_key
    AND ((e.jurisdiction_scope IS NULL AND i.jurisdiction_scope IS NULL) OR e.jurisdiction_scope = i.jurisdiction_scope)
    AND e.organization_id = i.organization_id
    AND e.valid_from = i.valid_from
);

COMMIT;
